function busiestRoom(n: number, meetings: number[][]): number {
  const ms = [...meetings].sort((a, b) => a[0] - b[0]);
  const endAt = new Array(n).fill(0), count = new Array(n).fill(0);
  for (const [s, e] of ms) {
    let room = -1;
    for (let i = 0; i < n; i++) if (endAt[i] <= s) { room = i; break; }
    if (room >= 0) endAt[room] = e;
    else {
      room = 0;
      for (let i = 1; i < n; i++) if (endAt[i] < endAt[room]) room = i;
      endAt[room] += e - s;
    }
    count[room]++;
  }
  return count.indexOf(Math.max(...count));
}

