class Solution:
    def busiestRoom(self, n: int, meetings: List[List[int]]) -> int:
        end_at, count = [0] * n, [0] * n
        for s, e in sorted(meetings):
            room = next((i for i in range(n) if end_at[i] <= s), -1)
            if room >= 0:
                end_at[room] = e
            else:
                room = min(range(n), key=lambda i: (end_at[i], i))
                end_at[room] += e - s
            count[room] += 1
        return count.index(max(count))

