class MinHeap<T> {
  private a: T[] = [];
  constructor(private less: (x: T, y: T) => boolean) {}
  get size() { return this.a.length; }
  peek(): T { return this.a[0]; }
  push(v: T): void {
    const a = this.a; a.push(v);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!this.less(a[i], a[p])) break;
      [a[i], a[p]] = [a[p], a[i]]; i = p;
    }
  }
  pop(): T {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1; let m = i;
        if (l < a.length && this.less(a[l], a[m])) m = l;
        if (r < a.length && this.less(a[r], a[m])) m = r;
        if (m === i) break;
        [a[i], a[m]] = [a[m], a[i]]; i = m;
      }
    }
    return top;
  }
}

function busiestRoom(n: number, meetings: number[][]): number {
  const ms = [...meetings].sort((a, b) => a[0] - b[0]);
  const free = new MinHeap<number>((x, y) => x < y);
  for (let i = 0; i < n; i++) free.push(i);
  // busy rooms as [end, room], earliest end first, then lowest room
  const busy = new MinHeap<number[]>((x, y) => x[0] < y[0] || (x[0] === y[0] && x[1] < y[1]));
  const count = new Array(n).fill(0);
  for (const [s, e] of ms) {
    while (busy.size && busy.peek()[0] <= s) free.push(busy.pop()[1]);
    let room: number;
    if (free.size) {
      room = free.pop();
      busy.push([e, room]);
    } else {
      const [end, r] = busy.pop();
      room = r;
      busy.push([end + e - s, room]);
    }
    count[room]++;
  }
  let best = 0;
  for (let i = 1; i < n; i++) if (count[i] > count[best]) best = i;
  return best;
}

